<?php
require_once __DIR__.'/includes/db.php'; require_once __DIR__.'/includes/functions.php'; require_login();
$page_title='My learning'; $s=db()->prepare("SELECT c.id,c.title,c.category,e.progress,e.completed_at FROM enrollments e JOIN courses c ON c.id=e.course_id WHERE e.user_id=? ORDER BY e.enrolled_at DESC"); $s->execute([current_user()['id']]); $courses=$s->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $cid=(int)($_POST['course_id']??0); $progress=max(0,min(100,(int)($_POST['progress']??0))); $u=db()->prepare('UPDATE enrollments SET progress=?,completed_at=IF(?=100,NOW(),NULL) WHERE user_id=? AND course_id=?'); $u->execute([$progress,$progress,current_user()['id'],$cid]); flash('Learning progress updated.'); redirect('dashboard.php'); }
require __DIR__.'/includes/header.php'; ?>
<section class="page-heading"><p class="eyebrow">YOUR LEARNING SPACE</p><h1>Welcome, <?= e(current_user()['name']) ?>.</h1><p class="muted">A little progress each day adds up.</p></section>
<div class="metric-row"><div class="metric"><span>Enrolled courses</span><strong><?= count($courses) ?></strong></div><div class="metric"><span>Completed courses</span><strong><?= count(array_filter($courses,fn($c)=>(int)$c['progress']===100)) ?></strong></div><div class="metric"><span>Account</span><strong><?= current_user()['role']==='admin'?'Admin':'Student' ?></strong></div></div>
<section class="section-head"><div><p class="eyebrow">KEEP GOING</p><h2>My courses</h2></div><a href="<?= BASE_URL ?>/courses.php">Find courses →</a></section>
<?php if(!$courses): ?><div class="empty panel"><h3>Your learning journey starts here.</h3><p class="muted">You have not enrolled in any courses yet.</p><a class="button" href="<?= BASE_URL ?>/courses.php">Explore courses</a></div><?php else: ?><div class="grid"><?php foreach($courses as $c): ?><article class="panel"><span class="pill"><?= e($c['category']) ?></span><h3><?= e($c['title']) ?></h3><p><?= (int)$c['progress'] ?>% complete</p><div class="progress"><span style="width:<?= (int)$c['progress'] ?>%"></span></div><form class="progress-form" method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="course_id" value="<?= (int)$c['id'] ?>"><label>Update progress<select name="progress"><?php foreach([0,25,50,75,100] as $n): ?><option value="<?= $n ?>" <?= (int)$c['progress']===$n?'selected':'' ?>><?= $n ?>%</option><?php endforeach; ?></select></label><button class="button small">Save</button></form></article><?php endforeach; ?></div><?php endif; ?>
<?php require __DIR__.'/includes/footer.php'; ?>
